self.KB_CONTENT["card:793047"]={"id":"card:793047","ty":"card","sourceId":"793047","title":"『產生分錄底稿作業』的作業重點有哪些？","ver":"GP4以上","topic":"單身","keywords":["單身","單別","分錄","底稿"],"y":"explain","answer":"1.將產生之分錄底稿單別+底稿序號記錄在處理結果中。2.顯示方式起始底稿批號-序號至截止底稿批號-序號。3.同一張單據單身產生的底稿筆數超過底稿最大筆數時，即結束此作業。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
