self.KB_CONTENT["card:756611"]={"id":"card:756611","ty":"card","sourceId":"756611","title":"『庫存狀況查詢作業』中的『批號』為何？","ver":"iGP","topic":"庫存","keywords":["庫存","批號","狀況"],"y":"other","answer":"* 可點選(icon)或[F2]批號資料查詢。若空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
