self.KB_CONTENT["card:757371"]={"id":"card:757371","ty":"card","sourceId":"757371","title":"『進貨單建立作業』中的『廠商單號 (TG006)』為何？","ver":"iGP","topic":"進貨單","keywords":["進貨單","廠商","單號","號碼"],"y":"other","answer":"* 可空白，註記欄位。* 可記錄廠商之進貨單據號碼。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
