self.KB_CONTENT["card:754684"]={"id":"card:754684","ty":"card","sourceId":"754684","title":"『合約訂單建立作業』中的『金額 (TX015)』為何？","ver":"iGP","topic":"訂單","keywords":["訂單","單價","合約"],"y":"other","answer":"* 金額=數量×單價×折扣率。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
