self.KB_CONTENT["field:778718"]={"id":"field:778718","ty":"field","sourceId":"778718","title":"材料型態","ver":"GP4以上","topic":"","keywords":[],"job":"批次生產計劃維護-依開工日","code":"TB009","answer":"* 此料件用料型態碼。* 區分為1.直接材料、2.間接材料、3.廠商供料、4.不發料及5.客戶供料型態。","file":"fields.jsonl"};
